
"use client";

import { useState } from "react";
import {
  Phone, Wallet, User, Globe2, ChevronDown, Plus,
  Check, ShieldCheck, Zap, CreditCard, Heart, Mic,
  Grid3X3, Volume2, PhoneOff, Headphones, ArrowRight,
  History, Home, CircleHelp
} from "lucide-react";

const destinations = [
  { name: "Eritrea", code: "+291", flag: "🇪🇷" },
  { name: "Ethiopia", code: "+251", flag: "🇪🇹" },
  { name: "Sudan", code: "+249", flag: "🇸🇩" },
  { name: "Kenya", code: "+254", flag: "🇰🇪" },
];

const keypad = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "*", "0", "#"];

export default function HomePage() {
  const [destination, setDestination] = useState("Eritrea");
  const [phone, setPhone] = useState("");
  const [notice, setNotice] = useState("");
  const [demoCall, setDemoCall] = useState(false);
  const [muted, setMuted] = useState(false);
  const [speaker, setSpeaker] = useState(false);
  const [showKeypad, setShowKeypad] = useState(false);
  const [language, setLanguage] = useState("English");

  const selected = destinations.find((d) => d.name === destination)!;

  function addDigit(digit: string) {
    setPhone((previous) => previous + digit);
    setNotice("");
  }

  function handleCall() {
    if (!phone.trim()) {
      setNotice("Please enter a phone number first.");
      return;
    }
    setDemoCall(true);
    setNotice("Demo only: no real call has been placed. Calling is not connected yet.");
  }

  return (
    <main className="dewl-page">
      <header className="site-header">
        <a href="#" className="logo">
          <span className="logo-icon"><Phone size={27} /></span>
          <span className="logo-text">
            DEWL
            <small>CALL HOME. STAY CONNECTED. PAY LESS.</small>
          </span>
        </a>

        <nav className="main-nav">
          <a className="nav-current" href="#"><Home size={16} /> Home</a>
          <a href="#rates">Rates</a>
          <a href="#how">How It Works</a>
          <a href="#faq"><CircleHelp size={15} /> FAQ</a>
          <a href="#contact">Contact</a>
        </nav>

        <div className="header-actions">
          <label className="language-select">
            <Globe2 size={17} />
            <select value={language} onChange={(e) => setLanguage(e.target.value)}>
              <option>English</option>
              <option>Tigrinya</option>
              <option>Amharic</option>
            </select>
            <ChevronDown size={13} />
          </label>
          <a href="#account" className="account-link">
            <User size={16} /> My Account <ChevronDown size={13} />
          </a>
        </div>
      </header>

      <section className="hero-banner">
        <div className="hero-overlay">
          <span className="hero-kicker">STAY CONNECTED WITH THE PEOPLE YOU LOVE</span>
          <h1>Affordable Calls<br />to Eritrea</h1>
          <p>Clear, simple international calling<br />for our community.</p>
          <a href="#calling" className="hero-button">
            Get Started <ArrowRight size={17} />
          </a>
        </div>
      </section>

      <section className="main-panels" id="calling">
        {/* ACCOUNT AND RATES */}
        <section className="panel account-panel" id="account">
          <div className="panel-header">
            <span><User size={23} fill="currentColor" /> My Account</span>
            <a href="#account">Account <ArrowRight size={15} /></a>
          </div>

          <div className="account-content">
            <div className="greeting-box">
              <h2>Welcome to DEWL!</h2>
              <p>Your current balance:</p>
              <div className="balance-line">
                <strong>€12.50</strong>
                <button className="add-credit" onClick={() => setNotice("Payment services are not connected yet.")}>
                  <Wallet size={17} /> Add Credit
                </button>
              </div>
              <span className="demo-label">SAMPLE BALANCE · DEMO ONLY</span>
            </div>

            <div className="rates-section" id="rates">
              <h3><Headphones size={21} /> Our Rates</h3>
              <div className="rate-card">
                <span className="rate-flag">🇪🇷</span>
                <div className="rate-description">
                  <strong>Eritrea</strong>
                  <small>Mobile and landline</small>
                </div>
                <strong className="rate-price">Coming soon</strong>
              </div>
              <div className="rate-note">
                <ShieldCheck size={21} />
                <span>Applicable rates will be displayed before you connect.</span>
              </div>
            </div>
          </div>
        </section>

        {/* DIALER */}
        <section className="panel dialer-panel">
          <div className="panel-header">
            <span><Phone size={23} fill="currentColor" /> Make a Call</span>
            <span className="demo-tag">DEMO</span>
          </div>

          <div className="dialer-content">
            <label className="input-label">Destination</label>
            <div className="destination-select">
              <span className="destination-flag">{selected.flag}</span>
              <select value={destination} onChange={(e) => setDestination(e.target.value)}>
                {destinations.map((d) => (
                  <option key={d.name} value={d.name}>{d.name} ({d.code})</option>
                ))}
              </select>
              <ChevronDown size={17} />
            </div>

            <label className="input-label">Phone Number</label>
            <div className="phone-entry">
              <Phone size={19} />
              <span className="phone-code">{selected.code}</span>
              <input
                value={phone}
                onChange={(e) => {
                  setPhone(e.target.value.replace(/[^0-9]/g, ""));
                  setNotice("");
                }}
                placeholder="Enter phone number..."
                inputMode="numeric"
              />
            </div>

            <div className="number-pad">
              {keypad.map((digit) => (
                <button key={digit} onClick={() => addDigit(digit)}>
                  <strong>{digit}</strong>
                  <small>
                    {digit === "2" ? "ABC" : digit === "3" ? "DEF" :
                     digit === "4" ? "GHI" : digit === "5" ? "JKL" :
                     digit === "6" ? "MNO" : digit === "7" ? "PQRS" :
                     digit === "8" ? "TUV" : digit === "9" ? "WXYZ" :
                     digit === "0" ? "+" : "\u00a0"}
                  </small>
                </button>
              ))}
            </div>

            <button className="main-call-button" onClick={handleCall}>
              <Phone size={19} fill="currentColor" /> Call
            </button>
            {notice && <p className="call-notice" role="status">{notice}</p>}
          </div>
        </section>

        {/* CALL PREVIEW */}
        <section className="active-call-panel">
          <div className="call-status">
            <span className="status-dot" />
            {demoCall ? "DEMO CALL PREVIEW" : "CALL PREVIEW"}
          </div>

          <div className="caller-avatar"><User size={61} fill="white" /></div>
          <h2>{destination}</h2>
          <p className="caller-number">{selected.code} {phone || "7 XXX XXX XX"}</p>
          <p className="call-demo-warning">NOT CONNECTED · DEMONSTRATION ONLY</p>

          {showKeypad ? (
            <div className="call-mini-keypad">
              {["1", "2", "3", "4", "5", "6", "7", "8", "9", "*", "0", "#"].map((d) => (
                <button key={d} onClick={() => addDigit(d)}>{d}</button>
              ))}
            </div>
          ) : (
            <div className="call-controls">
              <button onClick={() => setMuted(!muted)} className={muted ? "control-selected" : ""}>
                <Mic size={23} />
                <small>{muted ? "Muted" : "Mute"}</small>
              </button>
              <button onClick={() => setShowKeypad(true)}>
                <Grid3X3 size={23} />
                <small>Keypad</small>
              </button>
              <button onClick={() => setSpeaker(!speaker)} className={speaker ? "control-selected" : ""}>
                <Volume2 size={23} />
                <small>Speaker</small>
              </button>
              <button className="end-call" onClick={() => {
                setDemoCall(false);
                setShowKeypad(false);
                setMuted(false);
                setSpeaker(false);
              }}>
                <PhoneOff size={23} />
                <small>End</small>
              </button>
            </div>
          )}

          {showKeypad && (
            <button className="close-call-keypad" onClick={() => setShowKeypad(false)}>
              Back to call controls
            </button>
          )}

          <p className="call-panel-foot">
            {demoCall ? "This is a visual demo, not a live telephone call." : "Your active call controls will appear here."}
          </p>
        </section>
      </section>

      {/* BOTTOM BENEFITS */}
      <section className="feature-strip" id="how">
        <div className="feature-item"><Zap size={27} /><span>Simple Activation</span></div>
        <div className="feature-item"><ShieldCheck size={29} /><span>Secure Account</span></div>
        <div className="feature-item"><Globe2 size={29} /><span>International Calling</span></div>
        <div className="feature-item"><CreditCard size={29} /><span>Prepaid Wallet</span></div>
        <div className="feature-item"><Heart size={29} /><span>Our Community, Our Priority</span></div>
      </section>

      <footer className="site-footer" id="contact">
  <span>© 2026 DEWL. All rights reserved.</span>
  <strong>CALL HOME. STAY CONNECTED. PAY LESS.</strong>
  <span>English · Tigrinya · Amharic</span>
  <a href="mailto:support@dewl.com">
    Contact DEWL <ArrowRight size={13} />
  </a>
</footer>
    </main>
  );
}
